46	test('the plan names each declared pack\'s gap, and skips what is not a canon pack', async () => {
47	  const packs = await loadPacks();
48	  const plan = planPackUpdates(packs, ['basics', 'local/mine', 'no-such-pack'], { packVersions: { basics: 0 } });
49	  const ids = plan.map((p) => p.id);
50	  assert.ok(ids.includes('basics'), 'the declared pack is planned');
51	  assert.ok(!ids.includes('mine') && !ids.includes('local/mine'), 'a local pack has no version and no update flow');
52	  assert.ok(!ids.includes('no-such-pack'), 'an id naming no canon pack is skipped, not an error');
53	  // The requires closure comes with it — resolveDeclaredPacks is what decides that,
54	  // and the plan must cover every pack the repo will actually be running.
55	  assert.deepEqual(ids, [...new Set(ids)], 'no pack is planned twice');
56	  for (const id of ids) assert.ok(packs.some((p) => p.id === id), `${id} is not a canon pack`);
57	  const basics = plan.find((p) => p.id === 'basics');
58	  assert.equal(basics.from, 0);
59	  assert.equal(basics.to, packs.find((p) => p.id === 'basics').version);
60	  assert.equal(basics.blocked, null);
